svg.script:
(function () {
  var tracks = [
    "Basshunter - DotA",
    "Nightcore - Angel with a Shotgun",
    "Eiffel 65 - I'm Blue",
    "Time is ticking (G4bby Remix)",
    "Nightcore - Stereo Hearts",
    "Manian - Raver's Fantasy",
    "Krewella - Alive"
  ];
  var elapsed = 87;
  var running = true;
  var stopped = false;
  var current = 0;
  var lastTick = Date.now();
  var interval = null;

  function byId(id) { return document.getElementById(id); }
  function formatTime(value) {
    var hours = Math.floor(value / 3600);
    var minutes = Math.floor((value % 3600) / 60);
    var seconds = value % 60;
    return [hours, minutes, seconds].map(function (part) {
      return String(part).padStart(2, '0');
    }).join(':');
  }
  function updateClock() {
    byId('elapsed-top').textContent = formatTime(elapsed);
  }
  function setPlaying(isPlaying) {
    running = isPlaying;
    stopped = false;
    lastTick = Date.now();
    document.documentElement.classList.toggle('is-paused', !isPlaying);
    byId('btn-play').style.filter = isPlaying ? 'brightness(1.18)' : '';
    byId('btn-pause').style.filter = isPlaying ? '' : 'brightness(1.18)';
    byId('playback-status').textContent = isPlaying ? 'PLAYING' : 'PAUSED';
  }
  function selectTrack(index) {
    current = (index + tracks.length) % tracks.length;
    elapsed = 0;
    byId('track-title').textContent = tracks[current];
    byId('selected-track-bg').setAttribute('y', String(245 + current * 8));
    tracks.forEach(function (_, i) {
      byId('playlist-track-' + i).setAttribute('fill', i === current ? '#64ee51' : '#e1e0d7');
    });
    updateClock();
    setPlaying(true);
  }
  function bindButton(id, action) {
    var el = byId(id);
    if (!el) return;
    el.addEventListener('click', action);
    el.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        action();
      }
    });
  }
  function tick() {
    if (!running) { lastTick = Date.now(); return; }
    var now = Date.now();
    var delta = Math.floor((now - lastTick) / 1000);
    if (delta > 0) {
      elapsed += delta;
      lastTick += delta * 1000;
      updateClock();
    }
  }
  function start() {
    updateClock();
    setPlaying(true);
    bindButton('btn-play', function () { setPlaying(true); });
    bindButton('btn-pause', function () { setPlaying(false); });
    bindButton('btn-stop', function () {
      elapsed = 0;
      updateClock();
      setPlaying(false);
      stopped = true;
      byId('playback-status').textContent = 'STOPPED';
    });
    bindButton('btn-next', function () { selectTrack(current + 1); });
    bindButton('btn-previous', function () { selectTrack(current - 1); });
    bindButton('btn-eject', function () { elapsed = 0; updateClock(); });
    tracks.forEach(function (_, i) {
      bindButton('playlist-track-' + i, function () { selectTrack(i); });
    });
    if (interval !== null) window.clearInterval(interval);
    interval = window.setInterval(tick, 200);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, { once: true });
  } else {
    start();
  }
})();
